import java.util.Scanner;

public class Main {
    static final int maxn = 510;
    static int n, m, P;
    static int[][] C = new int[maxn][maxn];
    static int[] f1 = new int[maxn];
    static int[][] f2 = new int[maxn][maxn];
    static int[] g1 = new int[maxn];
    static int[][] g2 = new int[maxn][maxn];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
            }
        }

        f1[0] = 1;
        g1[0] = 0;
        for (int i = 1; i <= n; i++) {
            f1[i] = 0;
            g1[i] = 0;
            for (int j = 1; j <= i; j++) {
                f1[i] = (int)((f1[i] + 1L * f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P);
                int t = (int)((1L * f1[j - 1] * g1[i - j] + 1L * g1[j - 1] * f1[i - j]) % P * (i + 1) % P);
                g1[i] = (int)((g1[i] + (1L * f1[j - 1] * f1[i - j] % P * (C[j][2] + C[i - j + 1][2]) % P + t) % P * C[i - 1][j - 1]) % P);
            }
            f1[i] = (int)((1L * (i + 1) * f1[i]) % P);
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                f2[i][j] = 0;
                g2[i][j] = 0;
            }
        }
        f2[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                f2[i][j] = f2[i - 1][j];
                g2[i][j] = g2[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    int valF = (i - k != 0) ? f2[i - k - 1][j - k] : 1;
                    f2[i][j] = (int)((f2[i][j] + 1L * valF * f1[k] % P * C[j][k]) % P);
                    int valG1 = (i - k != 0) ? g1[k] : 0;
                    int valG2 = (i - k != 0) ? g2[i - k - 1][j - k] : 0;
                    g2[i][j] = (int)((g2[i][j] + (1L * valF * valG1 + 1L * valG2 * f1[k]) % P * C[j][k]) % P);
                }
            }
        }

        System.out.println(g2[n][m]);
        sc.close();
    }
}

